    #[test]
    fn tags_distinguish_nested_empty_missing_and_unavailable_facts() {
        let PersistentRegistryTagMembers::Present(signs) =
            vanilla_persistent_registry_tag_members_26_1("minecraft:block", "minecraft:all_signs")
        else {
            panic!("missing nested block tag")
        };
        assert!(!signs.is_empty());
        assert_eq!(
            vanilla_persistent_registry_tag_members_26_1(
                "minecraft:block",
                "minecraft:incorrect_for_diamond_tool"
            ),
            PersistentRegistryTagMembers::Present(Vec::new())
        );
        assert_eq!(
            vanilla_persistent_registry_tag_members_26_1("minecraft:block", "minecraft:not_a_tag"),
            PersistentRegistryTagMembers::Absent
        );
        assert_eq!(
            vanilla_persistent_registry_tag_members_26_1("minecraft:mob_effect", "minecraft:any"),
            PersistentRegistryTagMembers::Absent
        );
        let PersistentRegistryTagMembers::Present(placeable) =
            vanilla_persistent_registry_tag_members_26_1(
                "minecraft:painting_variant",
                "minecraft:placeable",
            )
        else {
            panic!("missing painting placeable tag")
        };
        assert_eq!(placeable.len(), 47);
        assert_eq!(
            placeable.first().map(String::as_str),
            Some("minecraft:kebab")
        );
        assert_eq!(
            placeable.last().map(String::as_str),
            Some("minecraft:dennis")
        );
        for registry_id in [
            "minecraft:jukebox_song",
            "minecraft:villager_profession",
            "minecraft:villager_type",
            "minecraft:wolf_variant",
            "minecraft:wolf_sound_variant",
            "minecraft:pig_variant",
            "minecraft:pig_sound_variant",
            "minecraft:cow_variant",
            "minecraft:cow_sound_variant",
            "minecraft:chicken_variant",
            "minecraft:chicken_sound_variant",
            "minecraft:zombie_nautilus_variant",
            "minecraft:frog_variant",
            "minecraft:cat_variant",
            "minecraft:cat_sound_variant",
            "minecraft:trim_material",
            "minecraft:trim_pattern",
            "minecraft:dimension_type",
            "minecraft:chunk_generator",
        ] {
            assert_eq!(
                vanilla_persistent_registry_tag_members_26_1(registry_id, "minecraft:any"),
                PersistentRegistryTagMembers::Absent,
                "{registry_id}"
            );
        }
        assert_eq!(
            vanilla_persistent_registry_tag_members_26_1("example:registry", "minecraft:any"),
            PersistentRegistryTagMembers::Unavailable
        );
    }

